const DIALOGUES={afterStage1:{title:"✅ Equipment Ready",message:'\n        Doctor:\n        "The emergency room is prepared."\n\n        <br><br>\n\n        System:\n        "Patient monitoring can begin."\n\n        <br><br>\n\n        Patient condition:\n        🟠 Unstable\n        '},afterStage2:{title:"⚠️ ECG Analysis Complete",message:'\n        Monitor:\n        "Abnormal rhythm detected."\n\n        <br><br>\n\n        Doctor:\n        "We need the defibrillator immediately."\n\n        <br><br>\n\n        Patient condition:\n        ❤️ Arrhythmia\n        '},afterStage3:{title:"🔧 Defibrillator Restored",message:'\n        System:\n        "Device calibration completed."\n\n        <br><br>\n\n        Doctor:\n        "The defibrillator is ready."\n\n        <br><br>\n\n        Patient condition:\n        🟡 Improving\n        '},afterStage4:{title:"❤️ Patient Stabilized",message:'\n        Monitor:\n        "Vital signs returning to normal."\n\n        <br><br>\n\n        Doctor:\n        "Excellent work. The patient is stable."\n\n        <br><br>\n\n        Preparing final report...\n        '}};function showDialogue(n,e){const t=DIALOGUES[n];t?(stageContent.innerHTML=`\n\n\n        <div class="card dialogue">\n\n\n            <h1>\n                ${t.title}\n            </h1>\n\n\n            <br>\n\n\n            <p>\n                ${t.message}\n            </p>\n\n\n\n            <button id="continue-btn">\n\n                Continue\n\n            </button>\n\n\n        </div>\n\n\n    `,document.getElementById("continue-btn").onclick=e):e()}